/* Faceted tutorial filter for the "Find a Tutorial" page (browse/index.md).
 * Reads browse/catalog.json (generated by mkdocs/build_docs.py).
 * Facets: AND across facets, OR within a facet. State is kept in the URL query
 * string (?language=R&topic=lidar...) so filtered views can be linked/bookmarked.
 */
(function () {
  "use strict";

  var FACETS = [
    { key: "language", label: "Language / Tool" },
    { key: "system", label: "System & Data Product" },
    { key: "topic", label: "Topic", scroll: true },
    { key: "task", label: "Workflow / Task" },
    { key: "skill", label: "Skill Level" }
  ];

  function siteBase() {
    var el = document.getElementById("__config");
    var base = ".";
    if (el) {
      try { base = JSON.parse(el.textContent).base || "."; } catch (e) { /* ignore */ }
    }
    return new URL(base.replace(/\/?$/, "/"), window.location.href);
  }

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function readState() {
    var p = new URLSearchParams(window.location.search);
    var st = { q: p.get("q") || "" };
    FACETS.concat([{ key: "product" }]).forEach(function (f) { st[f.key] = p.getAll(f.key); });
    return st;
  }

  function writeState(st) {
    var p = new URLSearchParams();
    if (st.q) p.set("q", st.q);
    FACETS.concat([{ key: "product" }]).forEach(function (f) {
      st[f.key].forEach(function (v) { p.append(f.key, v); });
    });
    var qs = p.toString();
    history.replaceState(null, "", window.location.pathname + (qs ? "?" + qs : ""));
  }

  function asArray(v) { return Array.isArray(v) ? v : (v ? [v] : []); }

  function matchFacet(t, key, sel) {
    if (!sel.length) return true;
    if (key === "system") {
      // a tutorial matches a system if it is assigned to it, or uses a product from it
      var sys = [t.system].concat(t.productSystems || []);
      return sel.some(function (v) { return sys.indexOf(v) >= 0; });
    }
    var vals = asArray(t[key]);
    return sel.some(function (v) { return vals.indexOf(v) >= 0; });
  }

  function matchText(t, q) {
    if (!q) return true;
    var hay = (t.title + " " + t.description + " " + asArray(t.topic).join(" ") + " " +
               asArray(t.product).join(" ") + " " + asArray(t.language).join(" ")).toLowerCase();
    return q.toLowerCase().split(/\s+/).every(function (w) { return hay.indexOf(w) >= 0; });
  }

  function filterAll(data, st, skipKey) {
    return data.tutorials.filter(function (t) {
      if (!matchText(t, st.q)) return false;
      for (var i = 0; i < FACETS.length; i++) {
        var k = FACETS[i].key;
        if (k !== skipKey && !matchFacet(t, k, st[k])) return false;
      }
      if (skipKey !== "product" && !matchFacet(t, "product", st.product)) return false;
      return true;
    });
  }

  function countFor(list, key, value) {
    var n = 0;
    list.forEach(function (t) { if (matchFacet(t, key, [value])) n++; });
    return n;
  }

  function checkbox(key, value, label, checked, count, extraClass) {
    return '<label class="' + (extraClass || "") + '"><input type="checkbox" data-facet="' + key +
      '" value="' + esc(value) + '"' + (checked ? " checked" : "") + "> " + esc(label) +
      ' <span class="nds-count">(' + count + ")</span></label>";
  }

  function render(root, data, st, base) {
    var html = "";
    FACETS.forEach(function (f) {
      var pool = filterAll(data, st, f.key);
      var opts = data.facets[f.key] || [];
      var inner = "";
      opts.forEach(function (o) {
        var c = countFor(pool, f.key, o.value);
        var on = st[f.key].indexOf(o.value) >= 0;
        if (!c && !on) return;
        inner += checkbox(f.key, o.value, o.label, on, c);
        if (f.key === "system" && on) {
          // nested data products for a selected system
          var ppool = filterAll(data, st, "product");
          data.facets.product.forEach(function (p) {
            if (p.system !== o.value) return;
            var pc = countFor(ppool, "product", p.value);
            var pon = st.product.indexOf(p.value) >= 0;
            if (!pc && !pon) return;
            inner += checkbox("product", p.value, p.label, pon, pc, "nds-sub");
          });
        }
      });
      html += '<fieldset><legend>' + esc(f.label) + "</legend>" +
        (f.scroll ? '<div class="nds-scroll">' + inner + "</div>" : inner) + "</fieldset>";
    });

    var results = filterAll(data, st, null);
    var items = results.map(function (t) {
      var meta = asArray(t.language).join(", ");
      var skill = (data.facets.skill.filter(function (s) { return s.value === t.skill; })[0] || {}).label;
      if (skill) meta += (meta ? " · " : "") + skill;
      if (t.system) meta += (meta ? " · " : "") + t.system;
      return '<li><a class="nds-title" href="' + esc(new URL(t.url, base).href) + '">' + esc(t.title) + "</a>" +
        (t.description ? '<div class="nds-desc">' + esc(t.description) + "</div>" : "") +
        '<div class="nds-chips"><span class="nds-chip">' + esc(meta) + "</span></div></li>";
    }).join("");

    root.querySelector(".nds-filter-controls").innerHTML = html;
    root.querySelector(".nds-filter-status").innerHTML =
      "<strong>" + results.length + "</strong> of " + data.tutorials.length + " tutorials" +
      ' <button class="md-button" type="button" data-reset>Clear filters</button>';
    root.querySelector(".nds-results").innerHTML = items || "<li>No tutorials match these filters.</li>";
  }

  function init() {
    var root = document.getElementById("nds-filter");
    if (!root || root.dataset.ready) return;
    root.dataset.ready = "1";
    var base = siteBase();
    root.innerHTML =
      '<input class="nds-filter-text" type="search" placeholder="Filter by keyword, e.g. canopy height, DP3.30015, phenocam">' +
      '<div class="nds-filter-controls"></div><div class="nds-filter-status"></div><ul class="nds-results"></ul>';

    fetch(new URL("browse/catalog.json", base).href)
      .then(function (r) { return r.json(); })
      .then(function (data) {
        var st = readState();
        // a product given without its system (e.g. from a link) -> select the system so it shows
        st.product.forEach(function (code) {
          var p = data.facets.product.filter(function (x) { return x.value === code; })[0];
          if (p && st.system.indexOf(p.system) < 0) st.system.push(p.system);
        });
        var text = root.querySelector(".nds-filter-text");
        text.value = st.q;
        var update = function () { writeState(st); render(root, data, st, base); };

        text.addEventListener("input", function () { st.q = text.value.trim(); update(); });
        root.addEventListener("change", function (e) {
          var cb = e.target;
          if (!cb.dataset || !cb.dataset.facet) return;
          var arr = st[cb.dataset.facet];
          var i = arr.indexOf(cb.value);
          if (cb.checked && i < 0) arr.push(cb.value);
          if (!cb.checked && i >= 0) arr.splice(i, 1);
          if (cb.dataset.facet === "system" && !cb.checked) {
            // drop products of a deselected system
            var drop = data.facets.product.filter(function (p) { return p.system === cb.value; })
              .map(function (p) { return p.value; });
            st.product = st.product.filter(function (v) { return drop.indexOf(v) < 0; });
          }
          update();
        });
        root.addEventListener("click", function (e) {
          if (e.target.hasAttribute && e.target.hasAttribute("data-reset")) {
            st = { q: "" };
            FACETS.concat([{ key: "product" }]).forEach(function (f) { st[f.key] = []; });
            text.value = "";
            update();
          }
        });
        update();
      })
      .catch(function (err) {
        root.innerHTML = "<p>Could not load the tutorial catalog (" + esc(err) + ").</p>";
      });
  }

  if (window.document$ && typeof window.document$.subscribe === "function") {
    window.document$.subscribe(init); // Material instant navigation
  } else if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
